// FINAL IVX EXECUTIVE LAYER FORENSIC AUDIT — Phase 1: live inventory
const OWNER_EMAIL = "iperez4242@gmail.com";
const BASE = "https://api.ivxholding.com";

async function rmint() {
  const rm = await fetch(BASE + "/api/ivx/owner-passwordless-login", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email: OWNER_EMAIL }),
  });
  const rmj = await rm.json();
  if (rmj.accessToken) await Bun.file("/tmp/owner_at").write(rmj.accessToken);
  return rmj.accessToken || await Bun.file("/tmp/owner_at").text();
}
const token = await rmint();
console.log("token len=" + token.length);

async function getJSON(url) {
  const r = await fetch(url, { headers: { Authorization: "Bearer " + token } });
  const text = await r.text();
  let j = null; try { j = JSON.parse(text); } catch {}
  return { status: r.status, json: j, text };
}

// 1. /health baseline
const h = await fetch(BASE + "/health");
const hj = await h.json();
console.log("\n=== /health ===");
console.log("HTTP=" + h.status + " sha=" + hj.commit + " boot=" + hj.bootTime + " status=" + hj.status);

// 2. Executive Layer — full payload
console.log("\n=== GET /api/ivx/executive-layer ===");
const el = await getJSON(BASE + "/api/ivx/executive-layer");
console.log("HTTP=" + el.status);
await Bun.file("/tmp/exec-layer-live.json").write(el.text);
const elj = el.json;
if (elj) {
  // Walk every top-level key + nested
  const flat = (o, prefix, out) => {
    for (const k of Object.keys(o || {})) {
      const v = o[k];
      const path = prefix ? prefix + "." + k : k;
      if (v && typeof v === "object" && !Array.isArray(v)) flat(v, path, out);
      else if (Array.isArray(v)) out.push(path + " = [Array len=" + v.length + "] " + JSON.stringify(v.slice(0,2)).slice(0,200));
      else out.push(path + " = " + JSON.stringify(v));
    }
    return out;
  };
  const rows = flat(elj, "", []);
  console.log("Total leaf values: " + rows.length);
  for (const r of rows) console.log("  " + r);
}

// 3. Real-data separation (authoritative post-cleanup numbers)
console.log("\n=== GET /api/ivx/real-data/separation ===");
const rd = await getJSON(BASE + "/api/ivx/real-data/separation");
console.log("HTTP=" + rd.status);
console.log(rd.text.slice(0, 1500));

// 4. Financial ledger (funds received truth)
console.log("\n=== GET /api/ivx/real-data/financial-ledger ===");
const fl = await getJSON(BASE + "/api/ivx/real-data/financial-ledger");
console.log("HTTP=" + fl.status);
console.log(fl.text.slice(0, 800));

// 5. Owner dashboard (business side)
console.log("\n=== GET /api/ivx/owner-dashboard ===");
const od = await getJSON(BASE + "/api/ivx/owner-dashboard");
console.log("HTTP=" + od.status);
await Bun.file("/tmp/owner-dashboard-live.json").write(od.text);
console.log("(saved to /tmp/owner-dashboard-live.json, len=" + od.text.length + ")");

// 6. Engineering OS status (autonomous runs)
console.log("\n=== GET /api/ivx/engineering-os/status ===");
const eos = await getJSON(BASE + "/api/ivx/engineering-os/status");
console.log("HTTP=" + eos.status);
console.log(eos.text.slice(0, 1200));

// 7. Architecture map (autonomous run classification)
console.log("\n=== GET /api/ivx/real-data/architecture-map ===");
const am = await getJSON(BASE + "/api/ivx/real-data/architecture-map");
console.log("HTTP=" + am.status);
console.log(am.text.slice(0, 1500));

// 8. Investor-audit (per-investor drilldown)
console.log("\n=== GET /api/ivx/real-data/investor-audit ===");
const ia = await getJSON(BASE + "/api/ivx/real-data/investor-audit");
console.log("HTTP=" + ia.status);
console.log(ia.text.slice(0, 1500));

// 9. Outreach guardrails
console.log("\n=== GET /api/ivx/real-data/outreach-guardrails ===");
const og = await getJSON(BASE + "/api/ivx/real-data/outreach-guardrails");
console.log("HTTP=" + og.status);
console.log(og.text.slice(0, 600));

console.log("\n=== Phase 1 inventory complete ===");

