   222|
   223|// ── Helpers ──────────────────────────────────────────────────────────────────
   224|
   225|function usd(value: number): string {
   226|  return `$${Math.round(value).toLocaleString('en-US')}`;
   227|}
   228|
   229|function clamp(value: number, min: number = 0, max: number = 100): number {
   230|  if (!Number.isFinite(value)) return min;
   231|  return Math.max(min, Math.min(max, value));
   232|}
