   326|
   327|// ── 2. Strategic planner ────────────────────────────────────────────────────
   328|
   329|export function buildStrategicPlan(
   330|  impact: BusinessImpactDashboard,
   331|  command: CapitalCommandCenter,
   332|): StrategicPlan {
   333|  const pipeline = command.capitalPipeline;
   334|  const opps = impact.opportunitiesFound;
   335|  const raisedThisMonth = command.capitalRaisedThisMonth;
   336|  const activeRelationships = pipeline.activeInvestors + pipeline.activeBuyers;
   337|
   338|  const thirtyDay: StrategicGoal[] = [
   339|    {
   340|      title: command.bestInvestorToday ? `Advance ${command.bestInvestorToday.name}` : 'Build the investor pipeline',
   341|      metric: command.bestInvestorToday
   342|        ? `Book a meeting on ${command.bestInvestorToday.dealName} (match ${command.bestInvestorToday.matchScore}/100)`
   343|        : 'Add 5 qualified capital relationships to the CRM',
   344|      rationale: command.bestInvestorToday
   345|        ? 'Highest-fit capital source today — converting it is the fastest path to committed capital.'
   346|        : 'A populated CRM is the prerequisite for every downstream capital workflow.',
   347|    },
   348|    {
   349|      title: 'Clear the open risks',
   350|      metric: `Resolve ${command.dealsAtRisk.length} deal(s) at risk + ${command.followUpsNeeded.length} follow-up(s)`,
   351|      rationale: 'Protecting in-flight relationships preserves more value than starting new ones.',
   352|    },
   353|    {
   354|      title: 'Keep discovering opportunities',
   355|      metric: `Sustain ${Math.max(opps.week, 5)}+ scanned opportunities / week`,
   356|      rationale: `${opps.week} found this week — a steady top-of-funnel feeds the pipeline.`,
   357|    },
   358|  ];
   359|
   360|  const ninetyDay: StrategicGoal[] = [
   361|    {
   362|      title: 'Grow the qualified pipeline',
   363|      metric: `Reach ${Math.max(activeRelationships * 2, 10)} active investor/buyer relationships`,
   364|      rationale: `${activeRelationships} active today — doubling the qualified base compounds raise capacity.`,
   365|    },
   366|    {
   367|      title: 'Close the first tracked deal',
   368|      metric: pipeline.dealsInProgress > 0
   369|        ? `Move ${pipeline.dealsInProgress} in-progress deal(s) to committed`
   370|        : 'Originate and commit the first deal',
   371|      rationale: 'A first close validates the deployment platform end-to-end and unlocks references.',
