// Verify every displayed value against underlying Supabase rows + reproduce calculations.
const OWNER_EMAIL = "iperez4242@gmail.com";
const BASE = "https://api.ivxholding.com";

async function rmint() {
  const rm = await fetch(BASE + "/api/ivx/owner-passwordless-login", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email: OWNER_EMAIL }),
  });
  const rmj = await rm.json();
  if (rmj.accessToken) await Bun.file("/tmp/owner_at").write(rmj.accessToken);
  return rmj.accessToken || await Bun.file("/tmp/owner_at").text();
}
const token = await rmint();

async function getJSON(url) {
  const r = await fetch(url, { headers: { Authorization: "Bearer " + token } });
  const text = await r.text();
  let j = null; try { j = JSON.parse(text); } catch {}
  return { status: r.status, json: j, text };
}

console.log("=== PHASE 2-3: trace every value + verify calculations ===\n");

// Executive layer (captured)
const el = await getJSON(BASE + "/api/ivx/executive-layer");
const elj = el.json;
await Bun.file("/tmp/el.json").write(el.text);

// Pull capital command center directly (source for investor pipeline + deal pipeline)
console.log("--- Capital Command Center (source of pipeline figures) ---");
const cc = await getJSON(BASE + "/api/ivx/capital-command-center");
console.log("HTTP=" + cc.status + " len=" + cc.text.length);
if (cc.json) {
  const c = cc.json;
  const p = c.capitalPipeline || {};
  console.log("capitalPipeline.totalPipeline = " + p.totalPipeline);
  console.log("capitalPipeline.weightedPipeline = " + p.weightedPipeline);
  console.log("capitalPipeline.capitalCommitted = " + p.capitalCommitted);
  console.log("capitalPipeline.activeInvestors = " + p.activeInvestors);
  console.log("capitalPipeline.activeBuyers = " + p.activeBuyers);
  console.log("capitalPipeline.dealsInProgress = " + p.dealsInProgress);
  console.log("capitalRaisedThisMonth = " + c.capitalRaisedThisMonth);
  console.log("bestInvestorToday = " + JSON.stringify(c.bestInvestorToday));
  console.log("bestBuyerToday = " + JSON.stringify(c.bestBuyerToday));
  console.log("meetingsNeeded.length = " + (c.meetingsNeeded?.length ?? 0));
  console.log("followUpsNeeded.length = " + (c.followUpsNeeded?.length ?? 0));
  console.log("dealsAtRisk.length = " + (c.dealsAtRisk?.length ?? 0));
}

// Autonomous dashboard (source for product health + scorecards)
console.log("\n--- Autonomous Dashboard (source for product health + scorecards) ---");
const ad = await getJSON(BASE + "/api/ivx/autonomous-dashboard");
console.log("HTTP=" + ad.status);
if (ad.json) {
  const a = ad.json;
  console.log("buckets = " + JSON.stringify(a.buckets));
  console.log("incidents = " + JSON.stringify(a.subsystems?.incidents));
  console.log("capabilities.length = " + (a.capabilities?.length ?? 0));
  const caps = a.capabilities || [];
  const online = caps.filter(x => x.state === "online").length;
  const partial = caps.filter(x => x.state === "partial").length;
  console.log("capabilities online=" + online + " partial=" + partial + " total=" + caps.length);
  console.log("aiGatewayConfigured = " + a.environment?.aiGatewayConfigured);
}

// Scheduler state (source for autonomousActions.totalRuns)
console.log("\n--- Scheduler State (source for autonomousActions totalRuns=450) ---");
const ss = await getJSON(BASE + "/api/ivx/autonomous-scheduler/state");
console.log("HTTP=" + ss.status);
if (ss.json) {
  const s = ss.json;
  const jobs = Object.values(s.jobs || {});
  let totalRuns = 0;
  for (const j of jobs) {
    totalRuns += j.runCount || 0;
    console.log("  job " + j.kind + " runCount=" + j.runCount + " lastStatus=" + j.lastStatus + " lastRunAt=" + j.lastRunAt + " summary=" + (j.lastSummary || "").slice(0, 80));
  }
  console.log("SUM runCount across all jobs = " + totalRuns);
  console.log("schedulerEnabled = " + s.enabled);
}

// Engineering OS tasks (source for execution tracking + scorecard engineering)
console.log("\n--- Engineering OS Tasks (source for executionTracking + verified count) ---");
const eos = await getJSON(BASE + "/api/ivx/engineering-os/status");
if (eos.json) {
  console.log("counts = " + JSON.stringify(eos.json.counts));
}

// Owner dashboard (deals/investors source)
console.log("\n--- Owner Dashboard ---");
const od = await getJSON(BASE + "/api/ivx/owner-dashboard");
const odj = od.json;
if (odj) {
  console.log("deals = " + JSON.stringify(odj.deals)?.slice(0, 400));
  console.log("investors count = " + (odj.investors?.length ?? odj.investorCount ?? "n/a"));
  console.log("buyers = " + JSON.stringify(odj.buyers)?.slice(0, 200));
  console.log("waitlist = " + (odj.waitlist?.length ?? odj.waitlistCount));
  console.log("revenue = " + JSON.stringify(odj.revenue));
  console.log("transactions = " + JSON.stringify(odj.transactions));
  console.log("casaRosario = " + JSON.stringify(odj.casaRosario)?.slice(0, 200));
}

// Real-data separation (authoritative category breakdown)
console.log("\n--- Real-data separation (authoritative totals) ---");
const rd = await getJSON(BASE + "/api/ivx/real-data/separation");
if (rd.json) {
  for (const cat of rd.json.separation?.categories || []) {
    console.log("  " + cat.key + " " + cat.label + " = " + cat.value + " (count=" + cat.count + ", amountUsd=" + cat.amountUsd + ", sourceIds=" + (cat.sourceRecordIds?.length ?? 0) + ")");
    console.log("    note: " + cat.note);
  }
}

// Financial ledger (funds-received truth)
console.log("\n--- Financial Ledger (funds received truth) ---");
const fl = await getJSON(BASE + "/api/ivx/real-data/financial-ledger");
if (fl.json) {
  const s = fl.json.summary || {};
  console.log("total=" + s.total + " committedCapital=" + s.committedCapital + " fundsReceived=" + s.fundsReceived + " returned=" + s.returned + " cancelled=" + s.cancelled);
  console.log("byStatus = " + JSON.stringify(s.byStatus));
  console.log("transactions.length = " + (fl.json.transactions?.length ?? 0));
}

// Architecture map (autonomous run classification)
console.log("\n--- Architecture Map (autonomous run classification) ---");
const am = await getJSON(BASE + "/api/ivx/real-data/architecture-map");
if (am.json?.map?.autonomousRunClassification) {
  console.log("classification = " + JSON.stringify(am.json.map.autonomousRunClassification));
}

// Outreach guardrails
console.log("\n--- Outreach Guardrails ---");
const og = await getJSON(BASE + "/api/ivx/real-data/outreach-guardrails");
if (og.json?.auditTrail) {
  const at = og.json.auditTrail;
  console.log("totalEvents=" + at.totalEvents + " sent=" + at.sent + " delivered=" + at.delivered + " replied=" + at.replied + " bounced=" + at.bounced + " unsubscribed=" + at.unsubscribed);
}

// Investors list — pull the 3 active ones
console.log("\n--- Investors (CRM) ---");
const inv = await getJSON(BASE + "/api/ivx/investors?limit=20");
if (Array.isArray(inv.json)) {
  console.log("investors returned = " + inv.json.length);
  for (const i of inv.json.slice(0, 10)) {
    console.log("  " + i.id + " | " + i.name + " | " + i.company + " | status=" + i.status + " | stage=" + i.stage + " | amount=" + i.amount + " | data_origin=" + i.data_origin + " | verification=" + i.verification_status);
  }
} else {
  console.log("HTTP=" + inv.status + " body=" + inv.text.slice(0, 400));
}

// Deals list — pull the 3 deals that sum to $4,925,000
console.log("\n--- Deals (jv_deals) ---");
const deals = await getJSON(BASE + "/api/ivx/jv-deals?limit=20");
let dealSum = 0;
if (Array.isArray(deals.json)) {
  console.log("deals returned = " + deals.json.length);
  for (const d of deals.json) {
    const amt = Number(d.investment_required ?? d.funding_goal ?? d.amount ?? 0);
    dealSum += amt;
    console.log("  " + d.id + " | " + d.title + " | status=" + d.status + " | stage=" + d.stage + " | investment_required=" + amt + " | data_origin=" + d.data_origin);
  }
  console.log("SUM of deal investment_required = " + dealSum);
} else {
  console.log("HTTP=" + deals.status + " body=" + deals.text.slice(0, 400));
}

console.log("\n=== Phase 2-3 data collection complete ===");

