// Phase 2-3b: verify $4,925,000 deal sum row-by-row + pull scheduler/owner-dashboard raw
const OWNER_EMAIL = "iperez4242@gmail.com";
const BASE = "https://api.ivxholding.com";

async function rmint() {
  const rm = await fetch(BASE + "/api/ivx/owner-passwordless-login", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email: OWNER_EMAIL }),
  });
  const rmj = await rm.json();
  if (rmj.accessToken) await Bun.file("/tmp/owner_at").write(rmj.accessToken);
  return rmj.accessToken || await Bun.file("/tmp/owner_at").text();
}
const token = await rmint();

async function getJSON(url) {
  const r = await fetch(url, { headers: { Authorization: "Bearer " + token } });
  const text = await r.text();
  let j = null; try { j = JSON.parse(text); } catch {}
  return { status: r.status, json: j, text };
}

// 1. Deals — full list with amounts, verify $4,925,000 sum
console.log("=== DEALS — verify $4,925,000 sum row-by-row ===");
const deals = await getJSON(BASE + "/api/ivx/jv-deals?limit=50");
const dealsArr = deals.json?.deals || [];
let sum = 0;
for (const d of dealsArr) {
  const amt = Number(d.investment_required ?? d.funding_goal ?? d.amount ?? 0);
  sum += amt;
  console.log(`  ${d.id} | ${d.title} | investment_required=${amt} | status=${d.status} | data_origin=${d.data_origin ?? "n/a"}`);
}
console.log(`SUM of ${dealsArr.length} deals = $${sum.toLocaleString()}`);
console.log(`Executive layer claims: $4,925,000 → MATCH=${sum === 4925000}`);

// 2. Investors — full active list (the 3 "active")
console.log("\n=== INVESTORS — verify 3 active claim ===");
const inv = await getJSON(BASE + "/api/ivx/investors?limit=50");
const invArr = inv.json?.investors || [];
let activeCount = 0;
for (const i of invArr) {
  const isActive = i.status === "active" || i.stage === "active" || i.verification_status === "verified_real";
  if (isActive) activeCount++;
  console.log(`  ${i.id} | ${i.name?.slice(0,50)} | status=${i.status} | stage=${i.stage} | verification=${i.verification_status} | data_origin=${i.data_origin ?? "n/a"}`);
}
console.log(`Total investors returned: ${invArr.length}, active/verified: ${activeCount}`);
console.log(`Executive layer claims: 3 active investors → CHECK`);

// 3. Owner dashboard — raw top-level keys
console.log("\n=== OWNER DASHBOARD — raw shape ===");
const od = await getJSON(BASE + "/api/ivx/owner-dashboard");
const odj = od.json || {};
console.log("top keys: " + Object.keys(odj).join(", "));
for (const k of Object.keys(odj)) {
  const v = odj[k];
  if (Array.isArray(v)) console.log(`  ${k} = [Array len=${v.length}]`);
  else if (v && typeof v === "object") console.log(`  ${k} = ${JSON.stringify(v).slice(0,200)}`);
  else console.log(`  ${k} = ${JSON.stringify(v)}`);
}

// 4. Scheduler — try alternate paths
console.log("\n=== SCHEDULER — find the route returning totalRuns=450 ===");
for (const path of ["/api/ivx/autonomous-core", "/api/ivx/autonomous-os", "/api/ivx/scheduler/state", "/api/ivx/autonomous/scheduler", "/api/ivx/owner-ai/autonomous"]) {
  const r = await getJSON(BASE + path);
  if (r.status === 200) {
    console.log(`  ${path} → 200 len=${r.text.length}`);
    // Look for runCount / totalRuns / jobs
    const t = r.text;
    if (t.includes("runCount") || t.includes("totalRuns") || t.includes("jobs")) {
      console.log("    contains runCount/totalRuns/jobs — saving");
      await Bun.file("/tmp/autonomous-raw.json").write(r.text);
      const jj = r.json;
      const jobs = jj?.scheduler?.jobs || jj?.jobs || jj?.state?.jobs || {};
      let totalRuns = 0;
      for (const jk of Object.keys(jobs)) {
        const j = jobs[jk];
        totalRuns += j?.runCount || 0;
        console.log(`    job ${jk}: runCount=${j?.runCount} lastStatus=${j?.lastStatus} summary=${(j?.lastSummary || "").slice(0,70)}`);
      }
      console.log(`    SUM runCount = ${totalRuns}`);
    }
  } else {
    console.log(`  ${path} → ${r.status}`);
  }
}

// 5. Capital command center raw
console.log("\n=== CAPITAL COMMAND CENTER — raw shape ===");
const cc = await getJSON(BASE + "/api/ivx/capital-command-center");
console.log("HTTP=" + cc.status + " len=" + cc.text.length);
console.log("body: " + cc.text.slice(0, 1200));

console.log("\n=== Phase 2-3b complete ===");

